protected void init()
{
    api = XAPI_APIS::GetUserRoles;
    super();
}

protected void postRun()
{
    int pos, lastPos, colonPos, q1, q2;
    str segment;

    if (!responseText)
    {
        return;
    }

    // Walk forward to find the last "recid" in the UserRoles array.
    // The last entry is the most recently added user role.
    pos = strScan(responseText, '"recid"', 1, strLen(responseText));
    while (pos > 0)
    {
        lastPos = pos;
        pos     = strScan(responseText, '"recid"', pos + 1, strLen(responseText) - pos);
    }

    if (lastPos)
    {
        segment  = subStr(responseText, lastPos, strLen(responseText) - lastPos + 1);
        colonPos = strScan(segment, ':', 1, strLen(segment));
        q1       = strScan(segment, '"', colonPos + 1, strLen(segment) - colonPos);
        q2       = strScan(segment, '"', q1 + 1,       strLen(segment) - q1);
        logKey   = 'UserRoles';
        logValue = subStr(segment, q1 + 1, q2 - q1 - 1);
    }
}

protected str body()
{
    Map configMap = new Map(Types::String, Types::String);

    configMap.insert('<DataAreaId>',  curExt());
    configMap.insert('<custAccount>', XAPI_APILogTable::getValueByKey(XAPI_APIS::CreateCustomer, 'CustAccount'));

    return this.prepareBody(configMap);
}
